{"command":"$ErrorActionPreference='SilentlyContinue'
"=== Соседние проекты в Documents\MiniMax ==="
Get-ChildItem 'C:\Users\spay\Documents\MiniMax' -Force | Select-Object Mode,LastWriteTime,Name | Format-Table -AutoSize | Out-String
"=== Установленные туннели/инструменты ==="
foreach ($t in 'cloudflared','ngrok','tailscale','frpc','ssh') {
  $c = Get-Command $t -ErrorAction SilentlyContinue
  if ($c) { "$t -> $($c.Source)" } else { "$t -> НЕТ" }
}
"=== Слушающие порты (список) ==="
Get-NetTCPConnection -State Listen -ErrorAction SilentlyContinue | Select-Object -ExpandProperty LocalPort | Sort-Object -Unique | Select-Object -First 40","description":"Поиск соседних проектов и туннельных инструментов"}

{"command":"$ErrorActionPreference='SilentlyContinue'
"=== Процессы на ключевых портах ==="
$ports = 554,9230,9990,18789,25808,10808,2179,1234,2869,5040
$conns = Get-NetTCPConnection -State Listen | Where-Object { $ports -contains $_.LocalPort }
foreach ($c in $conns) {
  $p = Get-Process -Id $c.OwningProcess -ErrorAction SilentlyContinue
  "{0,-6} {1,-28} {2}" -f $c.LocalPort, $c.OwningProcess, "$($p.ProcessName) ($($p.Path))"
}
"=== Docker контейнеры ==="
docker ps --format '{{.Names}} | {{.Image}} | {{.Ports}}' 2>&1
"=== Tailscale ==="
& 'C:\Program Files\Tailscale\tailscale.exe' status 2>&1 | Select-Object -First 10","description":"Идентификация сервисов на портах, контейнеры, статус Tailscale"}
